<script setup lang="ts">
import {computed,onUnmounted,ref,watch} from 'vue';import {useRoute,useRouter} from 'vue-router';import {useApplication} from '../../application';import Icon from '../../shared/Icon.vue';
import GovernanceListFrame from './GovernanceListFrame.vue';import GovernanceDrawer from './GovernanceDrawer.vue';import {useGovernanceList} from './useGovernanceList';import {kindLabels,localTime,type DatasetPage,type DatasetDetail,type WorkbenchSample} from './workbench-types';
const app=useApplication(),ops=app.operationsCommands,route=useRoute(),router=useRouter(),list=useGovernanceList<DatasetPage>('datasets');
const drawer=ref<'create'|'detail'|null>(null),detail=ref<DatasetDetail|null>(null),samples=ref<WorkbenchSample[]>([]),version=ref(''),copyVersion=ref(''),kind=ref<WorkbenchSample['kind']>('ASR'),content=ref(''),reference=ref(''),audio1=ref<File|null>(null),audio2=ref<File|null>(null),error=ref(''),notice=ref(''),busy=ref(false);let epoch=0;
const locked=computed(()=>busy.value||ops.pending.value||!ops.available.value),audio=computed(()=>!['MINUTES','ENTITY','EVIDENCE'].includes(kind.value)),pair=computed(()=>kind.value.startsWith('VOICE_'));
const hint=computed(()=>({ASR:'逐字参考转写，保留评测约定中的标点与大小写。',DIARIZATION:'填写 JSON 时间轴，采样率 16000；例如 [{"start":0,"end":48000,"speaker":"A"}]。说话人名称可以不同，评测会匹配标签。',MINUTES:'填写事实、行动项及证据核对标准。生成结果需要另一名管理员逐项人工评分。',ENTITY:'填写去重实体 JSON 数组，例如 ["PERSON:张三","PRODUCT:产品甲"]。',EVIDENCE:'填写结论编号与正确证据编号的 JSON 映射，例如 {"C1":["S1","S2"]}。',VOICE_SAME:'两份音频应来自同一位已授权的人员。',VOICE_DIFFERENT:'两份音频应来自不同的已授权人员。'}[kind.value]));
function failure(cause:unknown){error.value=cause instanceof Error?cause.message:'操作尚未确认，请保留原请求。';}
function create(){epoch++;drawer.value='create';detail.value=null;error.value='';version.value='';samples.value=[];}
async function open(id:string){const turn=++epoch;drawer.value='detail';detail.value=null;error.value='';try{const value=await ops.read<DatasetDetail>('/api/v1/operations/datasets/'+id);if(turn===epoch){detail.value=value;copyVersion.value=value.version+'-copy';await router.replace({query:{...route.query,selected:id}});}}catch(cause){if(turn===epoch)failure(cause);}}
function close(){if(busy.value)return;epoch++;drawer.value=null;void router.replace({query:{...route.query,selected:undefined}});}
function file(event:Event,second=false){const value=(event.target as HTMLInputElement).files?.[0]??null;if(second)audio2.value=value;else audio1.value=value;}
async function add(){if(locked.value)return;const turn=epoch;error.value='';busy.value=true;try{if(samples.value.length>=50)throw new Error('当前版本最多 50 个样本。');let input=content.value.trim(),input2:string|null=null,expected=pair.value?(kind.value==='VOICE_SAME'?'true':'false'):reference.value.trim();if(!expected)throw new Error('请填写参考标注。');if(['DIARIZATION','ENTITY','EVIDENCE'].includes(kind.value))JSON.parse(expected);if(audio.value){if(!audio1.value||pair.value&&!audio2.value)throw new Error('请选择所需音频。');for(const file of pair.value?[audio1.value,audio2.value]:[audio1.value])if(pair.value&&file&&(file.size<96044||file.size>960044))throw new Error('声纹样本要求 3–30 秒，单声道 16kHz PCM WAV。');const asset=await ops.uploadSample(audio1.value);input='asset:'+asset.id;if(pair.value){const second=await ops.uploadSample(audio2.value!);input2='asset:'+second.id;}}if(!input)throw new Error('请填写样本内容。');if(turn!==epoch)return;samples.value=[...samples.value,{id:'sample-'+crypto.randomUUID(),kind:kind.value,input,input2,expected}];content.value='';reference.value='';audio1.value=null;audio2.value=null;}catch(cause){if(turn===epoch)failure(cause);}finally{if(turn===epoch)busy.value=false;}}
async function save(){if(locked.value)return;busy.value=true;error.value='';try{if(!/^[A-Za-z0-9_.:/-]{1,128}$/.test(version.value)||!samples.value.length)throw new Error('请填写有效版本标识并至少添加一个样本。');await ops.submit('/api/v1/operations/datasets',{version:version.value,samples:samples.value});notice.value='数据集版本已保存，样本与标注已冻结。';drawer.value=null;samples.value=[];await list.load();}catch(cause){failure(cause);}finally{busy.value=false;}}
async function copy(){if(locked.value||!detail.value)return;busy.value=true;error.value='';try{await ops.submit(`/api/v1/operations/datasets/${detail.value.id}/copies`,{version:copyVersion.value});notice.value='新版本已复制，原版本及历史评测保持可追溯。';drawer.value=null;await list.load();}catch(cause){failure(cause);}finally{busy.value=false;}}
watch(()=>route.query.selected,id=>{if(typeof id==='string'&&detail.value?.id!==id)void open(id);else if(typeof id!=='string'&&drawer.value==='detail'){epoch++;drawer.value=null;detail.value=null;}},{immediate:true});watch(()=>ops.pending.value,(pending,was)=>{if(was&&!pending&&!busy.value){drawer.value=null;samples.value=[];void list.load();}});onUnmounted(()=>epoch++);
</script>
<template><p v-if="notice" class="gov-success" role="status">{{notice}}</p><GovernanceListFrame title="评测数据集" description="管理可复现的样本与参考标注，每次保存生成不可变版本。" :counts="list.page.value?.counts??{}" :total="list.page.value?.total??null" :loading="list.loading.value" :error="list.error.value" v-model:query="list.query.value" :state="list.state()" :states="['SAVED']" :next-cursor="list.page.value?.nextCursor" :has-cursor="list.hasCursor()" @search="list.search" @filter="list.filter('state',$event)" @refresh="list.load" @next="list.next" @first="list.first"><template #actions><button class="btn primary" :disabled="locked" @click="create"><Icon name="plus"/>创建数据集</button></template><div class="gov-table-wrap"><table class="gov-table"><thead><tr><th>数据集版本</th><th>样本数</th><th>内容指纹</th><th>创建时间</th><th>操作</th></tr></thead><tbody><tr v-for="item in list.page.value?.items" :key="item.id"><td class="primary-cell"><button class="gov-link" @click="open(item.id)">{{item.title}}</button><span class="sub-cell">不可变版本</span></td><td class="gov-row-number">{{item.sampleCount}} 个</td><td class="gov-muted">{{item.contentSha.slice(0,16)}}…</td><td>{{localTime(item.createdAt)}}</td><td><button class="gov-link" @click="open(item.id)">查看样本</button></td></tr></tbody></table></div><div v-if="!list.page.value?.items.length" class="gov-empty"><Icon name="layers" :size="32"/><h3>还没有数据集</h3><p>添加会议样本与参考标注，为质量评测建立依据。</p></div></GovernanceListFrame>
<GovernanceDrawer v-if="drawer" :title="drawer==='create'?'创建数据集':'数据集版本'" :subtitle="drawer==='create'?'先检查样本，再保存版本。保存后通过复制创建下一版。':detail?.version" wide :busy="busy" @close="close"><p v-if="error" class="gov-error" role="alert">{{error}}</p><template v-if="drawer==='create'"><div class="gov-fields"><label>版本标识<input v-model="version" maxlength="128" placeholder="例如 weekly-review-v1" :disabled="locked"/><small>使用英文、数字、短横线或下划线，保持版本唯一。</small></label><label>样本类型<select v-model="kind" :disabled="locked"><option v-for="(label,key) in kindLabels" :key="key" :value="key">{{label}}</option></select></label><div class="gov-note">{{hint}}</div><template v-if="audio"><label class="gov-upload">{{pair?'第一份音频':'音频样本'}}<input :key="samples.length+'a'" type="file" accept="audio/wav,.wav" :disabled="locked" @change="file($event)"/><small>{{pair?'3–30':'1–120'}} 秒 · 16kHz · 单声道 · PCM 16 位 WAV</small></label><label v-if="pair" class="gov-upload">第二份音频<input :key="samples.length+'b'" type="file" accept="audio/wav,.wav" :disabled="locked" @change="file($event,true)"/></label></template><label v-else>会议原文 / 样本输入<textarea v-model="content" maxlength="16384" rows="5" :disabled="locked"/></label><label v-if="!pair">参考标注<textarea v-model="reference" maxlength="8192" rows="4" :disabled="locked"/></label><button type="button" class="btn" :disabled="locked||samples.length>=50" @click="add"><Icon name="plus"/>{{busy?'正在保存样本…':'加入样本列表'}}</button></div><h3 class="gov-section-title">待保存样本 · {{samples.length}} / 50</h3><ol class="sample-drafts"><li v-for="(sample,index) in samples" :key="sample.id"><details><summary>{{kindLabels[sample.kind]}} · 样本 {{index+1}}</summary><p>{{sample.input.startsWith('asset:')?'已保存受控音频':sample.input}}</p><pre>{{sample.expected}}</pre></details><button class="btn sm" :disabled="locked" :aria-label="`删除样本 ${index+1}`" @click="samples=samples.filter(s=>s.id!==sample.id)"><Icon name="trash"/></button></li></ol></template><template v-else-if="detail"><dl class="gov-definition"><dt>版本</dt><dd>{{detail.version}}</dd><dt>样本总数</dt><dd>{{detail.samples.length}}</dd><dt>内容指纹</dt><dd>{{detail.contentSha}}</dd></dl><h3 class="gov-section-title">样本与参考标注</h3><details v-for="(sample,index) in detail.samples" :key="sample.id" class="sample-detail"><summary>{{String(index+1).padStart(2,'0')}} · {{kindLabels[sample.kind]}}</summary><p class="gov-muted">{{sample.input.startsWith('asset:')?'受控音频引用':sample.input}}</p><pre class="gov-report-pre">{{sample.expected}}</pre></details><h3 class="gov-section-title">复制为新版本</h3><div class="gov-fields"><label>新版本标识<input v-model="copyVersion" maxlength="128" :disabled="locked"/></label></div></template><p v-else class="gov-muted">正在读取样本…</p><template #footer><button class="btn" :disabled="busy" @click="close">关闭</button><button v-if="drawer==='create'" class="btn primary" :disabled="locked||!version||!samples.length" @click="save">保存数据集版本</button><button v-else class="btn primary" :disabled="locked||!detail||!copyVersion" @click="copy"><Icon name="copy"/>复制版本</button></template></GovernanceDrawer></template>
<style scoped>.sample-drafts{list-style:none;padding:0;display:grid;gap:12px}.sample-drafts li{display:flex;gap:10px;align-items:flex-start;border:1px solid #e9e9ef;border-radius:8px;padding:14px;font-size:12px}.sample-drafts details{flex:1;min-width:0}.sample-drafts pre{white-space:pre-wrap;overflow-wrap:anywhere}.sample-detail{font-size:12px;border-bottom:1px solid #efeff4;padding:14px 0}.sample-detail summary,.sample-drafts summary{cursor:pointer;font-weight:600}</style>
